type LocalizedTree = LocalizedText | {
    readonly [key: string]: LocalizedTree;
};
function selectLocale(node: LocalizedTree, locale: SupportedLocale): unknown {
    if (typeof node.en === 'string')
        return (node as LocalizedText)[locale];
    return Object.fromEntries(Object.entries(node).map(([key, value]) => [
        key,
        selectLocale(value as LocalizedTree, locale),
    ]));
}
export const REPORT_EXPORT_CORE_COPY = Object.fromEntries((['en', 'ar', 'fr', 'de', 'es', 'ru', 'zh'] as const).map((locale) => [
    locale,
    selectLocale(copyMatrix, locale),
])) as Record<SupportedLocale, {
    catalog: Record<string, {
        title: string;
        description: string;
        bound: string;
    }>;
    core: Record<string, unknown>;
}>;
